const reclaimExpiredTasks = `-- name: ReclaimExpiredTasks :many
UPDATE zdx_tasks
SET status = 'ready',
    updated_at = NOW()
WHERE status = 'active'
  AND NOT EXISTS (
    SELECT 1 FROM zdx_reservations r
    WHERE r.target_type = 'task'
      AND r.target_id = zdx_tasks.id
      AND r.released_at IS NULL
      AND r.lease_expires_at > NOW()
  )
  AND NOT EXISTS (
    SELECT 1 FROM zdx_reservations r
    JOIN zdx_agents a ON a.id = r.claimed_by
    WHERE r.target_type = 'task'
      AND r.target_id = zdx_tasks.id
      AND r.released_at IS NULL
      AND a.status IN ('paused', 'draining')
  )
  AND NOT EXISTS (
    SELECT 1 FROM zdx_reservations r
    JOIN zdx_agents a ON a.id = r.claimed_by
    WHERE r.target_type = 'task'
      AND r.target_id = zdx_tasks.id
      AND r.released_at IS NULL
      AND a.status = 'disconnected'
      AND a.disconnect_at IS NOT NULL
      AND a.disconnect_at > NOW() - $1::interval
  )
  AND status != 'done'
RETURNING id, project_id, title, text, feature, status, reason, issue, depends, test_plan, test_refs, task_group, spec, target_branch, created_at, completed_at, updated_at
`

type ReclaimExpiredTasksRow struct {
	ID           string             `db:"id" json:"id"`
	ProjectID    int32              `db:"project_id" json:"project_id"`
	Title        string             `db:"title" json:"title"`
	Text         string             `db:"text" json:"text"`
	Feature      string             `db:"feature" json:"feature"`
	Status       string             `db:"status" json:"status"`
	Reason       string             `db:"reason" json:"reason"`
	Issue        string             `db:"issue" json:"issue"`
	Depends      string             `db:"depends" json:"depends"`
	TestPlan     string             `db:"test_plan" json:"test_plan"`
	TestRefs     string             `db:"test_refs" json:"test_refs"`
	TaskGroup    string             `db:"task_group" json:"task_group"`
	Spec         string             `db:"spec" json:"spec"`
	TargetBranch string             `db:"target_branch" json:"target_branch"`
	CreatedAt    pgtype.Timestamptz `db:"created_at" json:"created_at"`
	CompletedAt  pgtype.Timestamptz `db:"completed_at" json:"completed_at"`
	UpdatedAt    pgtype.Timestamptz `db:"updated_at" json:"updated_at"`
}

// Reset tasks that are marked active but have no live reservation. Tasks
// claimed by an agent currently in status='paused' or 'draining' are exempt.
// Tasks claimed by a 'disconnected' agent within the grace window (@disconnect_grace)
// are also exempt to allow clean reconnects. See TK-1363, TK-1365 / IS-602.
func (q *Queries) ReclaimExpiredTasks(ctx context.Context, disconnectGrace pgtype.Interval) ([]ReclaimExpiredTasksRow, error) {
	rows, err := q.db.Query(ctx, reclaimExpiredTasks, disconnectGrace)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ReclaimExpiredTasksRow
	for rows.Next() {
		var i ReclaimExpiredTasksRow
		if err := rows.Scan(
			&i.ID,
			&i.ProjectID,
			&i.Title,
			&i.Text,
			&i.Feature,
			&i.Status,
			&i.Reason,
			&i.Issue,
			&i.Depends,
			&i.TestPlan,
			&i.TestRefs,
			&i.TaskGroup,
			&i.Spec,
			&i.TargetBranch,
			&i.CreatedAt,
			&i.CompletedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

